import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { renderDomainTypes } from './domain-catalog.mjs';
import { FIXTURE as f } from './domain-fixtures.mjs';

/** Runs against the real disposable local PostgreSQL database, after scoped fixtures. */
export async function verifyDomainPostgres(db) {
  assert.equal(await renderDomainTypes(db),await readFile(new URL('../../src/types/domain.generated.ts',import.meta.url),'utf8'),
    'Real PostgreSQL catalog must match committed types generated by PGlite');
  const tables=(await db.query(`SELECT tablename,rowsecurity FROM pg_tables WHERE schemaname='app' ORDER BY tablename`)).rows;
  assert.equal(tables.length,17);
  assert.ok(tables.every(t=>t.rowsecurity));
  assert.equal((await db.query(`SELECT count(*)::int AS count FROM pg_policies WHERE schemaname='app'`)).rows[0].count,0);
  for (const role of ['anon','authenticated','service_role']) {
    assert.equal((await db.query(`SELECT has_schema_privilege($1,'app','USAGE') AS allowed`,[role])).rows[0].allowed,false);
    assert.equal((await db.query(`SELECT has_table_privilege($1,'app.people','SELECT') AS allowed`,[role])).rows[0].allowed,false);
  }
  const bad=(sql,params)=>assert.rejects(db.query(sql,params),e=>e.code==='23503');
  await bad(`INSERT INTO app.properties(tenant_id,community_id,code,label,kind) VALUES ($1,$2,'BAD','Bad tenant','lot')`,[f.villageTenant,f.condo]);
  await bad(`INSERT INTO app.memberships(tenant_id,person_id,valid_from) VALUES ($1,$2,now())`,[f.villageTenant,f.condoPerson]);
  await bad(`INSERT INTO app.property_relationships(tenant_id,community_id,property_id,person_id,kind,valid_from) VALUES ($1,$2,$3,$4,'owner',now())`,[f.villageTenant,f.village,f.lot,f.condoPerson]);
  await bad(`INSERT INTO app.import_rows(tenant_id,batch_id,row_number,record_kind,raw_payload) VALUES ($1,$2,2,'property','{}')`,[f.condoTenant,f.batch]);
  await bad(`INSERT INTO app.document_objects(tenant_id,uploaded_by_membership_id,display_name,content_type,size_bytes) VALUES ($1,$2,'Bad','application/pdf',1)`,[f.condoTenant,f.villageMember]);
  await bad(`INSERT INTO app.outbox_events(tenant_id,operation_id,sequence,event_type,payload) VALUES ($1,$2,2,'fixture.created','{}')`,[f.condoTenant,f.operation]);
  // Even an accidental broad DML grant cannot bypass enabled default-deny RLS.
  await db.query('BEGIN');
  try {
    for (const role of ['anon','authenticated']) {
      await db.query(`GRANT USAGE ON SCHEMA app TO ${role}; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA app TO ${role}; SET LOCAL ROLE ${role}`);
      for (const table of tables) assert.equal((await db.query(`SELECT count(*)::int AS count FROM app.${table.tablename}`)).rows[0].count,0);
      // Use a savepoint so a deliberately denied write does not abort the verification transaction.
      await db.query('SAVEPOINT denied_write');
      await assert.rejects(db.query(`INSERT INTO app.tenants(tenant_key,legal_name) VALUES ('bad-tenant','Denied')`),e=>e.code==='42501');
      await db.query('ROLLBACK TO SAVEPOINT denied_write');
      await db.query('RESET ROLE');
    }
  } finally { await db.query('ROLLBACK'); }
  console.log('S01 PostgreSQL: private schema, matching generated types, scoped foreign keys and default-deny RLS verified');
}

/** Two real connections race on the same unique business key. No single-connection simulation. */
export async function verifyDomainConcurrency(connect) {
  const clients=await Promise.all([connect(),connect()]);
  try {
    const results=await Promise.allSettled(clients.map(client=>client.query(
      `INSERT INTO app.operation_requests(tenant_id,actor_membership_id,operation,idempotency_key,request_sha256) VALUES ($1,$2,'fixture.concurrent','same-request',$3) RETURNING id`,
      [f.villageTenant,f.villageMember,'f'.repeat(64)])));
    assert.equal(results.filter(r=>r.status==='fulfilled').length,1);
    assert.equal(results.filter(r=>r.status==='rejected'&&r.reason.code==='23505').length,1);
    assert.equal(Number((await clients[0].query(`SELECT count(*) FROM app.operation_requests WHERE operation='fixture.concurrent' AND idempotency_key='same-request'`)).rows[0].count),1);
    console.log('S01 PostgreSQL: concurrent duplicate requests produced exactly one operation record');
  } finally { await Promise.all(clients.map(client=>client.end())); }
}
